// UploadAttachmentFile implements TodoAttachmentService.
func (s DefaultTodoAttachmentService) UploadAttachmentFile(ctx context.Context, r Request[TodoAttachmentUploadAttachmentFilePath, struct{}, files.Upload]) (*RigFile, error) {
	// The owning row first, through the repository, which is what makes this
	// tenant-scoped and owner-scoped without a second rule: you cannot upload to a
	// row you cannot read.
	row, err := s.repo.Get(ctx, r.Path.ID)
	if err != nil {
		return nil, err
	}

	f, err := s.files.Attach(ctx, files.AttachRequest{
		TenantID: r.Claims.TenantID,
		Upload:   r.Body,
		Owner:    files.Owner{Table: "todo_attachment", IDColumn: "id", TenantColumn: "tenant_id", FileColumn: "attachment_file_id", ID: row.ID},
		URL: func(fileID uuid.UUID, name string) string {
			return todoAttachmentAttachmentFileURL(row.ID, fileID, name)
		},
	})
	if err != nil {
		return nil, err
	}
	return newRigFile(f), nil
}

// DownloadAttachmentFile implements TodoAttachmentService.
func (s DefaultTodoAttachmentService) DownloadAttachmentFile(ctx context.Context, r Request[TodoAttachmentDownloadAttachmentFilePath, struct{}, struct{}]) (*files.Content, error) {
	row, err := s.repo.Get(ctx, r.Path.ID)
	if err != nil {
		return nil, err
	}

	// The identifier has to be this row's. Opening any file the tenant owns from
	// under any row would make the nesting decorative, and the nesting is what the
	// permission check hangs off.
	if row.AttachmentFileID != r.Path.FileID {
		return nil, rigerr.NotFound("no such file")
	}

	return s.files.Open(ctx, r.Claims.TenantID, r.Path.FileID, r.Path.Filename)
}
